fn mounted_group_fixture_grant(capacity:usize,release:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:64}}
fn mounted_group_fixture_observe(operation:impl FnOnce()->RetainedCloneStep,grant:RetainedCloneGrant){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(operation);assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
fn mounted_group_original_triple(row:&serde_json::Value)->(KernelMutation,MutationId,InverseMutation){
        let dependencies=row["dependencies"].as_array().unwrap().iter().map(|id|MutationId(id.as_str().unwrap().to_owned())).collect::<Vec<_>>();let inverse=serde_json::from_value::<Vec<u8>>(row["inverse"].clone()).unwrap();let forward=serde_json::from_value::<Vec<u8>>(row["forward"].clone()).unwrap();
        let source=MountedKernelMutationReceiptSource{document:ArtifactHandle(row["document"].as_u64().unwrap()as u128),mutation_id:row["mutationId"].as_str().unwrap(),invocation_id:row["invocationId"].as_str().unwrap(),schema:row["schema"].as_str().unwrap(),schema_separator:"",schema_suffix:"",author:row["author"].as_str().unwrap(),dependencies:&dependencies,inverse:&inverse,base_version:ArtifactVersion(row["baseVersion"].as_u64().unwrap()),timestamp:HybridLogicalTimestamp{actor:3,physical_ms:row["timestamp"].as_u64().unwrap(),logical:1},undo_policy:UndoPolicy::ExactBaseOnly};
        let mut owner=MountedKernelMutationReceipt::new(&source,forward);
        for _ in 0..100000{if owner.is_complete(){break;}let g=mounted_group_fixture_grant(owner.next_capacity_byte_demand(&source).unwrap(),owner.next_release_byte_demand());mounted_group_fixture_observe(||owner.advance(&source,g).unwrap(),g);}
        assert!(owner.is_complete());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take(mounted_group_fixture_grant(0,0)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));result
    }

#[test]
fn mounted_group_receipt_preserves_all_original_causal_vectors_and_exact_cancelled_allocations(){
    fn grant(capacity:usize,release:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:64}}
    fn observe(f:impl FnOnce()->RetainedCloneStep,g:RetainedCloneGrant)->RetainedCloneStep{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));step}
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    for row in law["cases"].as_array().unwrap(){
        let children=serde_json::from_value::<Vec<String>>(row["childEditIds"].clone()).unwrap();let source=MountedGroupReceiptSource{invocation_id:row["invocationId"].as_str().unwrap(),parent_edit_id:row["parentEditId"].as_str(),child_edit_ids:MountedGroupChildEditSource::OriginalStrings(&children)};
        for stop in law["cancelStops"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain(std::iter::once(None)){
            let(mut owner,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||MountedGroupReceipt::new(row["lanes"].as_array().unwrap().len(),&source).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
            let mut turns=0;
            for _ in 0..100000{if stop.is_some_and(|stop|turns>=stop)||owner.phase==8{break;}let g=grant(owner.next_capacity_byte_demand(&source).unwrap(),owner.next_metadata_release_byte_demand());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance_metadata(&source,RetainedCloneGrant{maximum_items:0,..g}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if g.maximum_capacity_bytes>0||g.maximum_release_bytes>0{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance_metadata(&source,RetainedCloneGrant{maximum_capacity_bytes:g.maximum_capacity_bytes.saturating_sub(1),maximum_release_bytes:g.maximum_release_bytes.saturating_sub(1),..g}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}observe(||owner.advance_metadata(&source,g).unwrap(),g);turns+=1;}
            let mut expected=Vec::new();let mut pointers=Vec::new();
            if stop.is_none(){assert_eq!(owner.phase,8);for lane in row["lanes"].as_array().unwrap(){let triple=mounted_group_original_triple(lane);pointers.push(triple.0.diff.payload.as_ptr());expected.push(triple.clone());let mut triple=Some(triple);for _ in 0..100000{if triple.is_none(){break;}let g=grant(0,0);observe(||owner.push_mutation_triple(&mut triple,g).unwrap(),g);}assert!(triple.is_none());}for member in row["members"].as_array().unwrap(){let document=ArtifactHandle(member["document"].as_u64().unwrap()as u128);let edit_id=member["editId"].as_str().unwrap();let target=owner.member_edits.len()+1;for _ in 0..100000{if owner.member_edits.len()==target{break;}let g=grant(owner.next_member_capacity_byte_demand(document,edit_id).unwrap(),owner.next_member_release_byte_demand());observe(||owner.push_member_edit(document,edit_id,g).unwrap(),g);}assert_eq!(owner.member_edits.len(),target);}assert!(owner.is_complete());let(moved,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take(grant(0,0)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(moved.inverse_group.invocation_id.0,source.invocation_id);assert_eq!(moved.command_edit_id.as_deref(),source.parent_edit_id);assert_eq!(moved.command_child_edit_ids,children);for(index,triple)in expected.iter().enumerate(){assert_eq!(moved.mutations[index],triple.0);assert_eq!(moved.mutations[index].diff.payload.as_ptr(),pointers[index]);assert_eq!(moved.inverse_group.mutations[index],triple.1);assert_eq!(moved.inverse_group.inverse_mutations[index],triple.2);}for(index,member)in row["members"].as_array().unwrap().iter().enumerate(){assert_eq!(moved.inverse_group.member_edits[index],EditRef{document:ArtifactHandle(member["document"].as_u64().unwrap()as u128),edit_id:member["editId"].as_str().unwrap().to_owned()});}let mut returned=Some(moved);let original_pointer=returned.as_ref().unwrap().mutations.as_ptr();let denied=RetainedCloneGrant{maximum_items:0,..grant(0,0)};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.retain_output(&mut returned,denied));assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(returned.as_ref().unwrap().mutations.as_ptr(),original_pointer);let g=grant(0,0);observe(||owner.retain_output(&mut returned,g),g);assert!(returned.is_none());assert_eq!(owner.mutations.as_ptr(),original_pointer);for _ in 0..100000{if owner.terminal_is_empty(){break;}let g=grant(0,owner.next_close_byte_demand());observe(||owner.close_step(g),g);}assert!(owner.terminal_is_empty());}
            for _ in 0..100000{if owner.terminal_is_empty(){break;}let g=grant(0,owner.next_close_byte_demand());if g.maximum_release_bytes>0{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(RetainedCloneGrant{maximum_release_bytes:g.maximum_release_bytes-1,..g}));assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}observe(||owner.close_step(g),g);}
            assert!(owner.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] Mounted group receipt={} stop={stop:?} fullcausaltriple/all4vectors/commandIDs preserved; birth/free separatelyfunded; decision0heap; terminal0heap",row["id"]);
        }
        for stop in 0..=20{
            let mut owner=MountedGroupReceipt::new(row["lanes"].as_array().unwrap().len(),&source).unwrap();
            for _ in 0..100000{if owner.phase==8{break;}let g=grant(owner.next_capacity_byte_demand(&source).unwrap(),owner.next_metadata_release_byte_demand());observe(||owner.advance_metadata(&source,g).unwrap(),g);}
            let mut originals=row["lanes"].as_array().unwrap().iter().map(|lane|Some(mounted_group_original_triple(lane))).collect::<Vec<_>>();let mut operation=0;let mut member=0;
            for _ in 0..stop{if operation<originals.len(){let g=grant(0,0);observe(||owner.push_mutation_triple(&mut originals[operation],g).unwrap(),g);if originals[operation].is_none(){operation+=1;}}else if member<row["members"].as_array().unwrap().len(){let input=&row["members"][member];let document=ArtifactHandle(input["document"].as_u64().unwrap()as u128);let id=input["editId"].as_str().unwrap();let before=owner.member_edits.len();let g=grant(owner.next_member_capacity_byte_demand(document,id).unwrap(),owner.next_member_release_byte_demand());observe(||owner.push_member_edit(document,id,g).unwrap(),g);if owner.member_edits.len()!=before{member+=1;}}}
            for _ in 0..100000{if owner.terminal_is_empty(){break;}let g=grant(0,owner.next_close_byte_demand());if g.maximum_release_bytes!=0{observe(||owner.close_step(grant(0,g.maximum_release_bytes-1)),grant(0,0));}observe(||owner.close_step(g),g);}assert!(owner.terminal_is_empty());
            println!("[DEBUG] Mounted group partialcausal receipt={} stop={stop} originaltriples/memberIDprefix retained; cancellationpaidexacteachallocation",row["id"]);
        }

    }
}

#[test]
fn mounted_group_receipt_borrows_noncontiguous_original_child_edits_without_temporary_backing(){
    struct OriginalRows { children:Vec<Box<String>> }
    impl MountedGroupPreparedChildEdits for OriginalRows {
        fn len(&self)->usize{self.children.len()}
        fn get(&self,index:usize)->Option<&str>{self.children.get(index).map(|id|id.as_str())}
    }
    fn grant(capacity:usize,release:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:64}}
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    for fixture in law["cases"].as_array().unwrap(){
        let children=fixture["childEditIds"].as_array().unwrap().iter().map(|id|Box::new(id.as_str().unwrap().to_owned())).collect::<Vec<_>>();
        let rows=OriginalRows{children};let pointers=rows.children.iter().map(|id|id.as_ptr()).collect::<Vec<_>>();
        let source=MountedGroupReceiptSource{invocation_id:fixture["invocationId"].as_str().unwrap(),parent_edit_id:fixture["parentEditId"].as_str(),child_edit_ids:MountedGroupChildEditSource::Ready(&rows)};
        for stop in [Some(0),Some(1),Some(3),Some(7),Some(15),None]{
            let(mut owner,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||MountedGroupReceipt::new(0,&source).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
            for turn in 0..100000{
                if owner.phase==8||stop.is_some_and(|stop|turn>=stop){break;}
                let g=grant(owner.next_capacity_byte_demand(&source).unwrap(),owner.next_metadata_release_byte_demand());
                for refused in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_capacity_bytes:g.maximum_capacity_bytes.saturating_sub(1),maximum_release_bytes:g.maximum_release_bytes.saturating_sub(1),..g}].into_iter().take(if g.maximum_capacity_bytes>0||g.maximum_release_bytes>0{2}else{1}){
                    let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance_metadata(&source,refused).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
                }
                let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance_metadata(&source,g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));
                for(index,id)in rows.children.iter().enumerate(){assert_eq!(id.as_ptr(),pointers[index]);assert_eq!(id.as_str(),fixture["childEditIds"][index].as_str().unwrap());}
            }
            if stop.is_none(){
                assert_eq!(owner.phase,8);assert_eq!(&*owner.command_children,&rows.children.iter().map(|id|id.as_str()).collect::<Vec<_>>());
                for edit in fixture["members"].as_array().unwrap(){let document=ArtifactHandle(edit["document"].as_u64().unwrap()as u128);let id=edit["editId"].as_str().unwrap();let target=owner.member_edits.len()+1;for _ in 0..100000{if owner.member_edits.len()==target{break;}let g=grant(owner.next_member_capacity_byte_demand(document,id).unwrap(),owner.next_member_release_byte_demand());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.push_member_edit(document,id,g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}
                let(output,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take(grant(0,0)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(output.command_child_edit_ids,rows.children.iter().map(|id|id.as_str()).collect::<Vec<_>>());assert_eq!(output.command_edit_id.as_deref(),source.parent_edit_id);
                let mut reclaim=MountedGroupReceipt::new(0,&source).unwrap();reclaim.invocation.close_step(grant(0,0));reclaim.parent.close_step(grant(0,0));*reclaim.member_edits=output.inverse_group.member_edits;*reclaim.command_children=output.command_child_edit_ids;reclaim.invocation=MountedReceiptBytes::from_original(output.inverse_group.invocation_id.0.into_bytes());reclaim.parent=MountedReceiptBytes::from_original(output.command_edit_id.unwrap_or_default().into_bytes());
                while !reclaim.terminal_is_empty(){let g=grant(0,reclaim.next_close_byte_demand());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||reclaim.close_step(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
            }
            while !owner.terminal_is_empty(){let g=grant(0,owner.next_close_byte_demand());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
            let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
            println!("[DEBUG] Borrowed original child rows={} stop={stop:?} pointer/order retained; no temporary ID backing; exact funded cancellation/output0heap",fixture["id"]);
        }
    }
}

#[test]
fn mounted_group_receipt_triple_prevalidation_retains_original8194_ids_until_exact_prefix_grants(){
    let law:serde_json::Value=serde_json::from_str(include_str!("../🪪️triple/🧫️fixtures/🔣️.json")).unwrap();let mut corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let row=corpus["cases"].as_array_mut().unwrap().iter_mut().find(|row|!row["lanes"].as_array().unwrap().is_empty()).unwrap();row["lanes"][0]["mutationId"]=format!("{}{}",law["prefix"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize),law["suffix"].as_str().unwrap()).into();
    let children=serde_json::from_value::<Vec<String>>(row["childEditIds"].clone()).unwrap();let source=MountedGroupReceiptSource{invocation_id:row["invocationId"].as_str().unwrap(),parent_edit_id:row["parentEditId"].as_str(),child_edit_ids:MountedGroupChildEditSource::OriginalStrings(&children)};let mut owner=MountedGroupReceipt::new(1,&source).unwrap();
    for _ in 0..100000{if owner.phase==8{break;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:owner.next_capacity_byte_demand(&source).unwrap(),maximum_release_bytes:owner.next_metadata_release_byte_demand(),maximum_depth:64};owner.advance_metadata(&source,grant).unwrap();}
    let mut original=Some(mounted_group_original_triple(&row["lanes"][0]));let pointer=original.as_ref().unwrap().0.id.0.as_ptr();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:64};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.push_mutation_triple(&mut original,grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(step.progress(),Default::default());assert!(original.is_some(),"zero-copy prevalidation must retain every original triple owner");assert_eq!(original.as_ref().unwrap().0.id.0.as_ptr(),pointer);
    for denied in [RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:64,..grant},RetainedCloneGrant{maximum_copy_bytes:2,..grant}]{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.push_mutation_triple(&mut original,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(original.as_ref().unwrap().0.id.0.as_ptr(),pointer);}
    let mut copied=0;for _ in 0..100000{if original.is_none(){break;}let grant=RetainedCloneGrant{maximum_copy_bytes:64,..grant};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.push_mutation_triple(&mut original,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));copied+=step.progress().copied_bytes;if original.is_some(){assert_eq!(original.as_ref().unwrap().0.id.0.as_ptr(),pointer);}else{assert_eq!(step.progress().copied_bytes,0);}}
    assert!(original.is_none());assert_eq!(copied,law["utf8Bytes"].as_u64().unwrap()as usize*3);assert_eq!(owner.mutations[0].id.0.as_ptr(),pointer);for _ in 0..100000{if owner.terminal_is_empty(){break;}owner.close_step(RetainedCloneGrant{maximum_release_bytes:owner.next_close_byte_demand(),maximum_copy_bytes:64,..grant});}assert!(owner.terminal_is_empty());
    let mut denied_owner=MountedGroupReceipt::new(1,&source).unwrap();for _ in 0..100000{if denied_owner.phase==8{break;}let g=RetainedCloneGrant{maximum_copy_bytes:64,maximum_capacity_bytes:denied_owner.next_capacity_byte_demand(&source).unwrap(),maximum_release_bytes:denied_owner.next_metadata_release_byte_demand(),..grant};denied_owner.advance_metadata(&source,g).unwrap();}
    let mut denied=Some(mounted_group_original_triple(&row["lanes"][0]));let target=&mut denied.as_mut().unwrap().2.target_mutation.0;let start=target.len()-2;target.replace_range(start..,"β");let original_pointer=denied.as_ref().unwrap().0.id.0.as_ptr();let mut refused=false;
    for _ in 0..100000{let g=RetainedCloneGrant{maximum_copy_bytes:64,..grant};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||denied_owner.push_mutation_triple(&mut denied,g));assert_eq!(heap.released_bytes,0);assert!(denied.is_some());assert_eq!(denied.as_ref().unwrap().0.id.0.as_ptr(),original_pointer);match result{Ok(step)=>{assert_eq!(heap.requested_bytes,0);assert!(step.progress().fits(g));},Err(error)=>{assert_eq!(heap.requested_bytes,match &error.message{std::borrow::Cow::Borrowed(_)=>0,std::borrow::Cow::Owned(message)=>message.capacity()});assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);refused=true;break;}}}assert!(refused);assert!(denied_owner.mutations.is_empty());
    let triple=denied.as_mut().unwrap();for field in 0..10{for _ in 0..100000{let demand=MountedGroupReceipt::mutation_demand(&triple.0,field);let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||MountedGroupReceipt::clear_mutation(&mut triple.0,field));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,demand));if done{break;}}}let demand=triple.1.0.capacity();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||MountedGroupReceipt::clear_text(&mut triple.1.0));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,demand));for field in 0..4{for _ in 0..100000{let demand=MountedGroupReceipt::inverse_demand(&triple.2,field);let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||MountedGroupReceipt::clear_inverse(&mut triple.2,field));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,demand));if done{break;}}}let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(denied.take()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for _ in 0..100000{if denied_owner.terminal_is_empty(){break;}denied_owner.close_step(RetainedCloneGrant{maximum_release_bytes:denied_owner.next_close_byte_demand(),..grant});}assert!(denied_owner.terminal_is_empty());println!("[DEBUG] original8194 triple IDs aggregate<=63/turn copied={copied}; zero-copy denial preservesSome/pointer; separate1unit0copy move; full causal owners physically closed");
}
